/* Account screens for the local prototype. */
(() => {
  const A = window.StockMateAuth;
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const options = (items, value) => items.map(([v, label]) => `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`).join('');
  const fieldError = '<div id="account-error" role="alert" class="error"></div>';
  window.StockMateAccountViews = {
    login() {
      return `<main class="auth-layout"><section class="auth-story" aria-label="Giới thiệu StockMate"><a class="brand" href="#login"><span class="logo" aria-hidden="true">▣</span>StockMate</a><div class="auth-intro"><div class="kicker">QUẢN LÝ TỒN KHO THÔNG MINH</div><h1>Nắm chắc tồn kho.<br>Chủ động nhập hàng.</h1><p>Theo dõi hàng hóa, nắm bắt nhu cầu và lên kế hoạch bổ sung trong một ứng dụng.</p><ul class="auth-features"><li><span aria-hidden="true">✓</span> Theo dõi xuất, nhập và tồn kho</li><li><span aria-hidden="true">✓</span> Cảnh báo khi cần bổ sung hàng</li><li><span aria-hidden="true">✓</span> Lập và phê duyệt đề xuất nhập hàng</li></ul></div><small>StockMate · Quản lý kho, chủ động mỗi ngày.</small></section><section class="auth-panel" aria-labelledby="login-title"><div class="auth-form"><div class="kicker">CHÀO MỪNG TRỞ LẠI</div><h2 id="login-title">Đăng nhập</h2><p class="sub">Đăng nhập để tiếp tục công việc cùng StockMate.</p><form id="login-form"><label>Tên đăng nhập<input name="username" autocomplete="username" required placeholder="Nhập tên đăng nhập" maxlength="32" autocapitalize="none" spellcheck="false"></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" required placeholder="Nhập mật khẩu"></label>${fieldError}<button class="primary" type="submit">Đăng nhập <span aria-hidden="true">→</span></button></form><p class="auth-support">Quên mật khẩu hoặc cần cấp tài khoản?<br><span>Vui lòng liên hệ quản trị viên của bạn.</span></p></div></section></main>`;
    },
    password(user) {
      return `<div class="card stock-form"><h2>${user.must_change_password?'Đổi mật khẩu tạm':'Đổi mật khẩu'}</h2><p class="sub">${user.must_change_password?'Bạn cần đổi mật khẩu trước khi sử dụng workspace.':'Thay đổi mật khẩu cho tài khoản '+esc(user.username)+'. Các phiên khác sẽ hết hiệu lực.'}</p><form id="password-form"><label>Mật khẩu hiện tại<input name="old_password" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới<input name="new_password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><label>Xác nhận mật khẩu mới<input name="confirmation" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><p class="help">8–128 ký tự, khác mật khẩu hiện tại.</p>${fieldError}<div class="form-footer"><button class="primary" type="submit">Lưu mật khẩu</button></div></form></div>`;
    },
    users(search, role, status) {
      const users=A.list(), filtered=users.filter(u=>(u.username+' '+u.full_name).toLowerCase().includes(search.toLowerCase())&&(!role||u.role===role)&&(!status||String(u.is_active)===status));
      const audit=A.audit().slice().reverse().slice(0,12), actions={CREATE_USER:'Tạo tài khoản',UPDATE_USER:'Cập nhật tài khoản',RESET_PASSWORD:'Cấp mật khẩu tạm',CHANGE_PASSWORD:'Đổi mật khẩu',LOGIN:'Đăng nhập',LOGOUT:'Đăng xuất'};
      return `<div class="heading"><div><div class="kicker">ADMIN / PEOPLE</div><h1>Quản trị tài khoản</h1><p>Cấp quyền phù hợp. Giữ đầy đủ lịch sử hoạt động.</p></div><a href="#user/new" class="button primary">+ Tạo tài khoản</a></div><div class="metrics"><div class="metric featured"><div class="label">Tổng tài khoản</div><div class="number">${users.length}</div><small>Bốn vai trò trong hệ thống</small></div><div class="metric"><div class="label">Đang hoạt động</div><div class="number">${users.filter(u=>u.is_active).length}</div><small>Được phép đăng nhập</small></div><div class="metric"><div class="label">Đã khóa</div><div class="number">${users.filter(u=>!u.is_active).length}</div><small>Giữ nguyên lịch sử</small></div><div class="metric"><div class="label">Cần đổi mật khẩu</div><div class="number">${users.filter(u=>u.must_change_password).length}</div><small>Đang sử dụng mật khẩu tạm</small></div></div><div class="card"><form id="user-filter" class="toolbar"><input name="search" class="search" aria-label="Tìm tài khoản" value="${esc(search)}" placeholder="Tìm username hoặc họ tên…"><select name="role" aria-label="Lọc vai trò" style="width:auto">${options([['','Tất cả vai trò'],...Object.entries(A.roleNames)],role)}</select><select name="status" aria-label="Lọc trạng thái" style="width:auto">${options([['','Tất cả trạng thái'],['true','Hoạt động'],['false','Đã khóa']],status)}</select><button type="submit" class="quiet">Lọc</button></form><div class="table-wrap"><table><thead><tr><th>Tài khoản</th><th>Họ tên</th><th>Vai trò</th><th>Trạng thái</th><th>Mật khẩu</th><th></th></tr></thead><tbody>${filtered.map(u=>`<tr><td><strong>${esc(u.username)}</strong></td><td>${esc(u.full_name)}</td><td><span class="pill ${u.role==='admin'?'info':'neutral'}">${A.roleNames[u.role]}</span></td><td><span class="pill ${u.is_active?'good':'bad'}">${u.is_active?'Hoạt động':'Đã khóa'}</span></td><td>${u.must_change_password?'<span class="pill warn">Cần đổi mật khẩu</span>':'Đã thiết lập'}</td><td><a href="#user/${u.id}">Chỉnh sửa →</a></td></tr>`).join('')||'<tr><td colspan="6">Không có tài khoản phù hợp.</td></tr>'}</tbody></table></div><p class="help">Không xóa tài khoản. Khóa tài khoản, đổi vai trò hoặc cấp lại mật khẩu sẽ yêu cầu đăng nhập lại.</p></div><div class="card"><h2>Hoạt động tài khoản gần đây</h2><div class="table-wrap"><table><thead><tr><th>Người thực hiện</th><th>Thao tác</th><th>Tài khoản liên quan</th><th>Thời gian</th></tr></thead><tbody>${audit.map(e=>`<tr><td>${esc(e.actor_name)}</td><td>${actions[e.action]||esc(e.action)}</td><td>${esc(e.target_name)}</td><td>${new Date(e.created_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})}</td></tr>`).join('')}</tbody></table></div></div>`;
    },
    user(id) {
      const u=id==='new'?null:A.list().find(u=>u.id===id);
      if(id!=='new'&&!u)return '<h1>Không tìm thấy tài khoản</h1>';
      const self=u?.id===A.current().id;
      return `<div class="heading"><div><div class="kicker">ADMIN / PEOPLE</div><h1>${u?'Chỉnh sửa tài khoản':'Tạo tài khoản'}</h1><p>${u?'Username được giữ nguyên để dễ đối chiếu.':'Cấp tài khoản và mật khẩu tạm cho người sử dụng.'}</p></div><a class="button" href="#users">← Danh sách</a></div><form class="card stock-form" id="user-form" data-id="${u?.id||''}"><div class="fields"><label>Username *<input name="username" required pattern="[a-zA-Z0-9._-]{3,32}" maxlength="32" value="${esc(u?.username||'')}" ${u?'readonly':''}><small>3–32 ký tự; không phân biệt chữ hoa/thường.</small></label><label>Họ tên *<input name="full_name" required maxlength="120" value="${esc(u?.full_name||'')}"></label><label>Vai trò *<select name="role" ${self?'disabled':''}>${options(Object.entries(A.roleNames),u?.role||'staff')}</select></label>${u?`<label>Trạng thái<select name="is_active" ${self?'disabled':''}>${options([['true','Hoạt động'],['false','Đã khóa']],String(u.is_active))}</select></label>`:'<label>Mật khẩu tạm *<input type="password" name="password" autocomplete="new-password" minlength="8" maxlength="128" required></label>'}</div><p class="help">${self?'Bạn không thể tự khóa hoặc tự bỏ quyền Admin.':u?'Lịch sử nghiệp vụ giữ nguyên khi đổi tên, vai trò hoặc khóa tài khoản.':'Người dùng phải đổi mật khẩu tạm ở lần đăng nhập tiếp theo. Không có đăng ký công khai.'}</p>${fieldError}<div class="form-footer">${u?`<button type="button" class="quiet" data-action="reset-user-password" data-id="${u.id}">Cấp mật khẩu tạm…</button>`:''}<button class="primary" type="submit">Lưu tài khoản</button></div></form>`;
    }
  };
})();
